import { useEffect, useMemo } from 'react';
import { ExternalLink, FileText, RefreshCw } from 'lucide-react';
import { Alert, Button, Card, EmptyState, Skeleton } from '../../../ui';
import { useTemplatePdfPreview } from '../../../lib/api/hooks/templates';
import { errorMessage } from '../../../lib/errors';
import type { RichDoc } from '../../../lib/rich-doc/types';
import { useDebouncedValue } from '../../../lib/useDebouncedValue';

/**
 * The real PDF of the template (task T15): what will be printed and signed, page by page, generated by
 * the API with the same layout. Desktop browsers show it inline; phones get a button to open it,
 * because mobile browsers do not embed PDFs.
 */

const PREVIEW_DELAY_MS = 800;

export function PdfPreview({ content, title }: { content: RichDoc; title: string }) {
  // Wait until typing pauses: every request renders the whole PDF on the server.
  const input = useDebouncedValue(useMemo(() => ({ contentFormat: 'rich-v2' as const, content, title: title.trim() || 'Sin título' }), [content, title]), PREVIEW_DELAY_MS);
  const pdf = useTemplatePdfPreview(input);
  // One object URL per generated PDF, released when replaced or on leaving.
  const url = useMemo(() => (pdf.data ? URL.createObjectURL(pdf.data) : null), [pdf.data]);
  useEffect(() => () => {
    if (url) URL.revokeObjectURL(url);
  }, [url]);

  if (pdf.isError) {
    return (
      <Alert tone="danger" title="No se pudo generar el PDF" action={<Button size="sm" icon={<RefreshCw />} onClick={() => void pdf.refetch()}>Reintentar</Button>}>
        {errorMessage(pdf.error)}
      </Alert>
    );
  }
  if (!url) return <Skeleton className="h-[70dvh] rounded-lg" />;

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-2 text-[13px] text-slate-500">
        <span className="flex items-center gap-1.5">
          <FileText className="size-4" aria-hidden="true" />
          Así se imprimirá y firmará. Los datos aparecen con su nombre.
          {pdf.isFetching && <span className="text-slate-400"> · actualizando…</span>}
        </span>
        <a href={url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-medium text-vino-700 hover:underline">
          <ExternalLink className="size-3.5" />
          Abrir en otra pestaña
        </a>
      </div>
      <iframe title="Vista previa en PDF" src={url} className="hidden h-[78dvh] w-full rounded-lg border border-slate-200 bg-slate-100 md:block" />
      <Card className="md:hidden">
        <EmptyState
          icon={<FileText />}
          title="PDF listo"
          description="En el móvil el PDF se abre aparte."
          action={
            <a href={url} target="_blank" rel="noreferrer">
              <Button variant="primary" icon={<ExternalLink />}>Abrir el PDF</Button>
            </a>
          }
        />
      </Card>
    </div>
  );
}
